const input = $input.first().json;
const headers = input.headers ?? {};
const provided = headers['x-sattva-webhook-hmac'] ?? headers['X-Sattva-Webhook-Hmac'];
const expected = $env.N8N_WEBHOOK_HMAC;
if (typeof expected !== 'string' || !expected || typeof provided !== 'string' || provided !== expected) {
  throw new Error('invalid x-sattva-webhook-hmac');
}
const payload = input.body ?? input;
if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
const forbidden = new Set(['bytes','pdf','path','nextcloud_folder_path','file_bytes']);
function assertNoForbidden(value) {
  if (value == null || typeof value !== 'object') return;
  for (const [key, child] of Object.entries(value)) {
    if (forbidden.has(key)) throw new Error('RED key forbidden in COA mapper: ' + key);
    assertNoForbidden(child);
  }
}
assertNoForbidden(payload);
if (typeof payload.filename !== 'string' || !payload.filename) throw new Error('filename must be a string');
if (typeof payload.sha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(payload.sha256)) throw new Error('sha256 must be 64 hex characters');
if (typeof payload.moisture_pct !== 'number' || !Number.isFinite(payload.moisture_pct)) throw new Error('moisture_pct must be a number');
if (typeof payload.spec_moisture_max !== 'number' || !Number.isFinite(payload.spec_moisture_max)) throw new Error('spec_moisture_max must be a number');
if (typeof payload.mesh_pass !== 'boolean') throw new Error('mesh_pass must be boolean');
if (typeof payload.spec_mesh_required !== 'boolean') throw new Error('spec_mesh_required must be boolean');
return [{ json: {
  filename: payload.filename,
  sha256: payload.sha256.toLowerCase(),
  moisture_pct: payload.moisture_pct,
  mesh_pass: payload.mesh_pass,
  spec_moisture_max: payload.spec_moisture_max,
  spec_mesh_required: payload.spec_mesh_required
} }];

const b = $input.first().json;
if (b == null || typeof b !== 'object' || Array.isArray(b)) throw new Error('payload required');
const forbidden = new Set(['bytes','pdf','path','nextcloud_folder_path','file_bytes']);
function assertNoForbidden(value) {
  if (value == null || typeof value !== 'object') return;
  for (const [key, child] of Object.entries(value)) {
    if (forbidden.has(key)) throw new Error('RED key forbidden in COA compare: ' + key);
    assertNoForbidden(child);
  }
}
assertNoForbidden(b);
if (typeof b.filename !== 'string' || !b.filename) throw new Error('filename must be a string');
if (typeof b.sha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(b.sha256)) throw new Error('sha256 must be 64 hex characters');
if (typeof b.moisture_pct !== 'number' || !Number.isFinite(b.moisture_pct)) throw new Error('moisture_pct must be a number');
if (typeof b.spec_moisture_max !== 'number' || !Number.isFinite(b.spec_moisture_max)) throw new Error('spec_moisture_max must be a number');
if (typeof b.mesh_pass !== 'boolean') throw new Error('mesh_pass must be boolean');
if (typeof b.spec_mesh_required !== 'boolean') throw new Error('spec_mesh_required must be boolean');
const coa_pass = b.moisture_pct <= b.spec_moisture_max && b.mesh_pass === b.spec_mesh_required;
return [{ json: { coa_pass, moisture_pct: b.moisture_pct, mesh_pass: b.mesh_pass, coa_sha256: b.sha256 } }];
